        rule(data[id], `tuning.json#${id}`, '');
    const tuning = data as unknown as TuningCatalog;
    if (!Number.isSafeInteger(tuning.OUTSIDE_TRIAL.wallRing3StoneMilli * tuning.RING4_TRIAL.stoneFactor))
        fail('tuning.json#RING4_TRIAL', 'stoneFactor', 'expected a safe integer Stone cost');
    return tuning;
}

export function validateItems(json: unknown): {definitions:Record<string,ItemDefinition>;ITEM_TRIAL:ItemTrial} {
    const root = record(json, 'items.json#catalog', 'entries');
    object({definitions:()=>{},ITEM_TRIAL:()=>{}})(root,'items.json#catalog','');
    const definitions = record(root.definitions,'items.json#catalog','definitions');
    if (!Object.keys(definitions).length) fail('items.json#catalog','definitions','expected nonempty object');
    const rarity: Rule = (v,r,f) => { if(!['common','rare','epic','legendary'].includes(v as string)) fail(r,f,'expected one of common|rare|epic|legendary'); };
    const skill = oneOf('management','technical','medical','combat','negotiation');
    for (const [id,value] of Object.entries(definitions)) {
        const ref = `items.json#${id}`;
        if(!/^[a-z][a-z0-9-]*$/.test(id))fail(ref,'id','expected stable lowercase id');
        const d=record(value,ref,'definition');
        object({name:text,category:oneOf('material','equipment','accessory','outfit','consumable'),rarity,
            kind:optional(oneOf('player','npc')),slot:optional(text),mainStat:optional(skill),secondaryStat:optional(skill),
            regen:optional(nonnegative),exclusiveClass:optional(text),trait:optional(text),basePriceMilli:nonnegative,
            building:optional(list(oneOf('mine','quarry','logging','weaver','sheep-pasture','herb-garden'))),
            family:optional(oneOf('metal','mineral','cloth','herb','paper'))})(d,ref,'');
        if(d.category==='material')oneOf('metal','mineral','cloth','herb','paper')(d.family,ref,'family');
        else if(d.family!==undefined)fail(ref,'family','material only');
        const wearable=['equipment','accessory','outfit'].includes(d.category as string);
        if(wearable){
            oneOf('player','npc')(d.kind,ref,'kind'); skill(d.mainStat,ref,'mainStat');
            const slots=d.category==='equipment'?['weapon']:d.category==='accessory'?['earrings','necklace','ring','hand']:['top','bottom','shoes','set'];
            oneOf(...slots)(d.slot,ref,'slot');
            if(d.rarity!=='common')skill(d.secondaryStat,ref,'secondaryStat');
            if(d.kind==='npc'&&d.regen!==undefined)fail(ref,'regen','Player only');
            if(d.kind==='player')nonnegative(d.regen,ref,'regen');
            if(d.rarity==='legendary')text(d.trait,ref,'trait');
            if(d.building!==undefined)fail(ref,'building','material only');
        } else {
            for(const key of ['kind','slot','mainStat','secondaryStat','regen','exclusiveClass','trait'])if(d[key]!==undefined)fail(ref,key,'wearable only');
            if(d.category==='material')list(oneOf('mine','quarry','logging','weaver','sheep-pasture','herb-garden'))(d.building,ref,'building');
            else if(d.building!==undefined)fail(ref,'building','material only');
        }
    }
    const rarities = (rule:Rule)=>object({common:rule,rare:rule,epic:rule,legendary:rule});
    const sale = (rule:Rule)=>object({common:rule,rare:rule,epic:rule});
    const potions=object({'1':positive,'2':positive,'3':positive});
    const bps:Rule=(v,r,f)=>{nonnegative(v,r,f);if((v as number)>10000)fail(r,f,'expected <= 10000');};
    object({marker:literal('TRIAL'),bonuses:rarities(object({main:positive,secondary:nonnegative,regen:positive})),
        setMultiplier:positive,marketCounts:sale(positive),marketPricesMilli:sale(positive),resaleBps:bps,
        potionPricesMilli:potions,potionHeal:potions,findOddsBps:sale(bps),materialOddsBps:rarities(bps),
        stackCap:positive,inventoryCap:positive,consumableCap:positive,storageCap:positive,storageWeeks:positive,
        effects:object(Object.fromEntries(['threshold','outputStep','outputPercent','outputCapPercent','securityStep','securityCap','authorityStep','marketStep','marketCapPercent','fatalStep','fatalCap','woundStep','woundFloor','wardenSecurity','crownAuthority','ironhideWoundReduction','ledgerOutputPercent'].map(k=>[k,positive])))})(root.ITEM_TRIAL,'items.json#ITEM_TRIAL','');
    return root as unknown as {definitions:Record<string,ItemDefinition>;ITEM_TRIAL:ItemTrial};
}

export function validateRecipes(json: unknown): {recipes:Record<string,RecipeDefinition>;CRAFT_TRIAL:CraftTrial} {
    const root=record(json,'recipes.json#catalog','entries');
    object({recipes:()=>{},CRAFT_TRIAL:()=>{}})(root,'recipes.json#catalog','');
    const family=oneOf('metal','mineral','cloth','herb','paper');
    const fees=object({rare:nonnegative,epic:nonnegative});
    const steps:Rule=(value,ref,field)=>{
        if(!Array.isArray(value)||value.some((n,i)=>!Number.isSafeInteger(n)||n<0||n>100||i>0&&n<=value[i-1]))
            fail(ref,field,'expected strictly ascending skill steps in [0, 100]');
    };
    object({marker:literal('TRIAL'),queueCap:positive,skillSteps:steps,drugStoreBase:nonnegative,
        slotFamily:object(Object.fromEntries(['weapon','earrings','necklace','ring','hand','top','bottom','shoes','set'].map(slot=>[slot,family]))),
        fees:object({refine:fees,upgrade:fees,potion:object({'1':nonnegative,'2':nonnegative,'3':nonnegative})})})(root.CRAFT_TRIAL,'recipes.json#CRAFT_TRIAL','');
    const trial=root.CRAFT_TRIAL as unknown as CraftTrial;
    const recipes=record(root.recipes,'recipes.json#catalog','recipes');
    if(!Object.keys(recipes).length)fail('recipes.json#catalog','recipes','expected nonempty object');
    // Read the validated data directly: importing the runtime ITEM_CATALOG here would
    // create a cycle through trial/items.ts, which also uses this validator module.
    const definitions=validateItems(itemJson).definitions;
    const tiers=['common','rare','epic'];
    for(const [id,value] of Object.entries(recipes)){
        const ref=`recipes.json#${id}`;
        if(!/^[a-z][a-z0-9-]*$/.test(id))fail(ref,'id','expected stable lowercase id');
        object({kind:oneOf('refine','upgrade','fixed'),workshops:list(oneOf('smithy','hospital','drug-store')),
            inputs:list(object({defId:text,count:positive})),output:text,feeMilli:nonnegative})(value,ref,'');
        const recipe=value as RecipeDefinition;
        if(new Set(recipe.workshops).size!==recipe.workshops.length)fail(ref,'workshops','duplicate workshop');
        if(!Object.hasOwn(definitions,recipe.output))fail(ref,'output','unknown item id');
        const output=definitions[recipe.output];
        if(output.rarity==='legendary')fail(ref,'output','Legendary output is forbidden');
        for(const [i,input] of recipe.inputs.entries()){
            if(!Object.hasOwn(definitions,input.defId))fail(ref,`inputs.${i}.defId`,'unknown item id');
            if(definitions[input.defId].rarity==='legendary')fail(ref,`inputs.${i}.defId`,'Legendary input is forbidden');
        }
        const inputs=recipe.inputs.map(input=>definitions[input.defId]);
        const outputFamily=output.family??(output.slot?trial.slotFamily[output.slot as keyof CraftTrial['slotFamily']]:'herb');
        if(recipe.kind==='refine'){
            if(inputs.length!==1||recipe.inputs[0].count!==2||inputs[0].category!=='material'||output.category!=='material')fail(ref,'inputs','refine requires 2 of one material');
            if(inputs[0].family!==output.family)fail(ref,'inputs','refine materials must have the same family');
        }
        if(recipe.kind==='upgrade'){
            if(inputs.length!==2||recipe.inputs.some(input=>input.count!==1)||inputs[0].category==='material'||inputs[1].category!=='material')fail(ref,'inputs','upgrade requires 1 item and 1 material');
            const item=inputs[0],material=inputs[1];
            const potions=item.category==='consumable'&&output.category==='consumable';
            if(!potions&&(!item.slot||item.slot!==output.slot||item.kind!==output.kind))fail(ref,'output','upgrade must preserve slot and kind');
            if(material.family!==outputFamily)fail(ref,'inputs',`material family must be ${outputFamily}`);
            if(material.rarity!==output.rarity)fail(ref,'inputs','material rarity must equal output rarity');
        }
        if(recipe.kind!=='fixed'&&(tiers.indexOf(output.rarity)!==tiers.indexOf(inputs[0].rarity)+1||!['common','rare'].includes(inputs[0].rarity)))
            fail(ref,'output','rarity must be one tier above input');
        if(recipe.kind!=='fixed'&&id!==`${recipe.kind}-${recipe.output}`)fail(ref,'id',`expected ${recipe.kind}-${recipe.output}`);
        const allowed=outputFamily==='herb'?['hospital','drug-store']:['metal','mineral','cloth'].includes(outputFamily)?['smithy']:[];
        if(!allowed.length||recipe.workshops.some(workshop=>!allowed.includes(workshop)))fail(ref,'workshops',`${outputFamily} recipes require ${allowed.join(' or ')}`);
        let expectedFee:number|undefined;
        if(output.category==='consumable'){
            const tier=/^heal-potion-([123])$/.exec(recipe.output)?.[1] as '1'|'2'|'3'|undefined;
            if(tier)expectedFee=trial.fees.potion[tier];
        } else if(recipe.kind!=='fixed')expectedFee=trial.fees[recipe.kind][output.rarity as 'rare'|'epic'];
        if(expectedFee===undefined)fail(ref,'feeMilli','no TRIAL fee for output');
        if(recipe.feeMilli!==expectedFee)fail(ref,'feeMilli',`must equal TRIAL fee ${expectedFee}`);
    }
    return root as unknown as {recipes:Record<string,RecipeDefinition>;CRAFT_TRIAL:CraftTrial};
}


export interface NpcLifeCatalog {
    origins: Readonly<Record<string, Readonly<{ name: string; summary: string }>>>;
    hobbies: Readonly<Record<string, Readonly<{ name: string }>>>;
    P7A_TRIAL: Readonly<{
        marker: 'TRIAL'; lustBase: readonly [number, number]; beauty: readonly [number, number];
        stressWork: number; stressRest: number; stressHalveAuthority: number; stressHalveAffection: number;
        stressResume: number; arousalDivisor: number; weeksPerYear: number; recentCap: number;
        sexExpCaps: Readonly<{ novice: number; professional: number; expert: number }>;
    }>;
}
export function validateNpcLife(json: unknown): NpcLifeCatalog {
    const root = record(json, 'npc-life.json#catalog', 'entries');
    object({ origins: () => {}, hobbies: () => {}, P7A_TRIAL: () => {} })(root, 'npc-life.json#catalog', '');
    for (const [key, minimum, schema] of [
        ['origins', 1, object({ name: text, summary: text })],
        ['hobbies', 2, object({ name: text })],
    ] as const) {
        const entries = record(root[key], 'npc-life.json#catalog', key);
        if (Object.keys(entries).length < minimum) fail('npc-life.json#catalog', key, `expected at least ${minimum} entries`);
        for (const [id, value] of Object.entries(entries)) {
            const ref = `npc-life.json#${id}`;
            if (!/^[a-z][a-z0-9_]*$/.test(id)) fail(ref, 'id', 'expected stable lowercase id');
            schema(value, ref, '');
        }
    }
    const stat: Rule = (value, ref, field) => {
        if (!Number.isSafeInteger(value) || (value as number) < 0 || (value as number) > 100)
            fail(ref, field, 'expected integer in [0, 100]');
    };
    const range: Rule = (value, ref, field) => {
        if (!Array.isArray(value) || value.length !== 2 || !value.every(n => Number.isSafeInteger(n) && n >= 0 && n <= 100) || value[0] > value[1])
            fail(ref, field, 'expected ascending integer range in [0, 100]');
    };
    object({ marker: literal('TRIAL'), lustBase: range, beauty: range, stressWork: nonnegative, stressRest: nonnegative,
        stressHalveAuthority: stat, stressHalveAffection: stat, stressResume: stat, arousalDivisor: positive,
        weeksPerYear: positive, recentCap: positive, sexExpCaps: object({ novice: positive, professional: positive, expert: positive })
    })(root.P7A_TRIAL, 'npc-life.json#P7A_TRIAL', '');
    return root as unknown as NpcLifeCatalog;
}

type NpcRange = readonly [number, number];
type NpcSourceId = 'guild' | 'auction-house' | 'slave-market' | 'auction-house-lot' | 'slave-market-lot';
type NpcSourceProfile = Readonly<{
    status: 'slave' | 'servant';
    mind: NpcRange;
    skills: NpcRange;
    beauty: NpcRange;
    obedience: NpcRange;
    affection: NpcRange;
    past: NpcRange;
    socialClass: readonly ('lower' | 'common' | 'skilled')[];
}>;
type NpcChoices<T> = Readonly<{ [K in keyof T]-?: readonly T[K][] }>;
type NpcAppearanceChoices = NpcChoices<Omit<CharacterAppearance, 'hair' | 'face' | 'measurements'>> & Readonly<{
    hair: NpcChoices<CharacterAppearance['hair']>;
    face: NpcChoices<CharacterAppearance['face']>;
    measurements: readonly (NonNullable<CharacterAppearance['measurements']> | null)[];
}>;
export interface NpcGeneratorCatalog {
    cultures: Readonly<Record<string, Readonly<{ name: string; given: readonly string[]; epithets: readonly string[] }>>>;
    originCulture: Readonly<Record<string, string>>;
    originProfile: Readonly<Record<string, Readonly<{
        birthplaceId: string; regionId: string; upbringing: string; occupation: Occupation; guildClass: 'common' | 'skilled';
    }>>>;
    sources: Readonly<Record<NpcSourceId, NpcSourceProfile>>;
    appearance: NpcAppearanceChoices;
    preferences: readonly string[];
    flaws: readonly string[];
    price: Readonly<{
        baseMilli: Readonly<Record<'guild' | 'auction-house' | 'slave-market' | 'lot', number>>;
        skillPointBps: number; beautyPointBps: number; sexExpLevelBps: number;
        levelValue: Readonly<Record<'novice' | 'professional' | 'expert', number>>;
        conditionFactor: number; sellShare: number;
    }>;
    P7B_TRIAL: Readonly<{
        marker: 'TRIAL'; age: NpcRange; ageWeightYoung: number; youngAge: NpcRange; olderAge: NpcRange;
        stockSize: number; startGoldMilli: number; npcCap: number; traitCount: NpcRange; statRange: NpcRange;
        profileAxisRange: NpcRange; contractWeeks: number; wageMilli: NpcRange;
        household: {
            unpaidAffectionLoss: number; unpaidObedienceLoss: number; mansionObedienceGain: number;
            stressObedienceLoss: number; unpaidRefusalWeeks: number; stressRefusalHits: number;
            lifelongAffectionMin: number; lifelongObedienceMin: number; lifelongAskGapWeeks: number;
            renewalWageMultiplier: number; renewalWageStepMilli: number; quadrantSplit: number;
        };
        professionalAtCount: number; expertAtCount: number;
    }>;
}
const npcSourceIds: readonly NpcSourceId[] = ['guild', 'auction-house', 'slave-market', 'auction-house-lot', 'slave-market-lot'];
const npcGeneratorFile = 'npc-generator.json';
const npcDataKey: Rule = (value, ref, field) => {
    if (typeof value !== 'string' || !/^[a-z][a-z0-9_]*$/.test(value)) fail(ref, field, 'expected stable lowercase id');
};
const nameWord: Rule = (value, ref, field) => {
    if (typeof value !== 'string' || !/^[A-Z][a-z]+$/.test(value)) fail(ref, field, 'expected one capitalized English word');
};
const within = ([minimum, maximum]: NpcRange): Rule => (value, ref, field) => {
    if (!Number.isSafeInteger(value) || (value as number) < minimum || (value as number) > maximum)
        fail(ref, field, `expected integer in [${minimum}, ${maximum}]`);
};
const ascending = (item: Rule): Rule => (value, ref, field) => {
    tuple([item, item])(value, ref, field);
    const [min, max] = value as NpcRange;
    if (min > max) fail(ref, field, 'expected an ascending inclusive range');
};
const denseChoices = (item: Rule, allowEmpty = false): Rule => (value, ref, field) => {
    const entries = readDenseArray(value);
    if (entries === null || (!allowEmpty && !entries.length)) fail(ref, field, allowEmpty ? 'expected dense array' : 'expected nonempty dense array');
    const checked = entries!;
    const keys = checked.map(entry => JSON.stringify(entry));
    if (new Set(keys).size !== keys.length) fail(ref, field, 'expected unique entries');
    checked.forEach((entry, index) => item(entry, ref, child(field, String(index))));
};
const npcWordIds = (entries: readonly { readonly id: string }[]) => oneOf(...entries.map(entry => entry.id));

export interface AcquisitionCatalog {
    AUCTION_TRIAL: Readonly<{
        marker: 'TRIAL'; rivalCount: NpcRange; ceilingBps: NpcRange; steadyBps: number; keenBps: number;
        openingBps: number; openingStepMilli: number; playerRaisesMilli: NpcRange; rivalStepMilli: number;
    }>;
    CARD_TRIAL: Readonly<{ marker: 'TRIAL'; topSkillCount: number }>;
    rivalNames: readonly string[];
}
export function validateNpcAcquisition(json: unknown): AcquisitionCatalog {
    const file = 'npc-acquisition.json';
    const ref = file + '#AUCTION_TRIAL';
    const root = record(json, file + '#catalog', 'entries');
    object({ AUCTION_TRIAL: record, CARD_TRIAL: record, rivalNames: denseChoices(text) })(root, file + '#catalog', '');
    object({ marker: literal('TRIAL'), rivalCount: ascending(positive), ceilingBps: ascending(positive),
        steadyBps: positive, keenBps: positive, openingBps: positive, openingStepMilli: positive,
        playerRaisesMilli: ascending(positive), rivalStepMilli: positive })(root.AUCTION_TRIAL, ref, '');
    object({ marker: literal('TRIAL'), topSkillCount: positive })(root.CARD_TRIAL, file + '#CARD_TRIAL', '');
    const data = root as unknown as AcquisitionCatalog;
    const auction = data.AUCTION_TRIAL;
    if (auction.rivalCount[1] > data.rivalNames.length) fail(ref, 'rivalCount', 'expected enough distinct rival names');
    if (!(auction.openingBps <= auction.ceilingBps[0] && auction.ceilingBps[0] < auction.steadyBps &&
        auction.steadyBps < auction.keenBps && auction.keenBps <= auction.ceilingBps[1]))
        fail(ref, 'ceilingBps', 'expected opening <= floor < steady < keen <= ceiling');
    if (auction.playerRaisesMilli[0] === auction.playerRaisesMilli[1]) fail(ref, 'playerRaisesMilli', 'expected two distinct raises');
    for (const field of ['openingStepMilli', 'rivalStepMilli'] as const) {
        if (auction[field] % SOCIAL_RESOURCE_SCALE) fail(ref, field, 'expected whole Gold steps');
    }
    for (const [index, amount] of auction.playerRaisesMilli.entries()) {
        if (amount % SOCIAL_RESOURCE_SCALE) fail(ref, 'playerRaisesMilli[' + index + ']', 'expected whole Gold steps');
    }
    return data;
}

export function validateNpcGenerator(json: unknown): NpcGeneratorCatalog {
    const ref = `${npcGeneratorFile}#catalog`;
    const root = record(json, ref, 'entries');
    object({ cultures: () => {}, originCulture: record, originProfile: record, sources: () => {},
        appearance: record, preferences: denseChoices(npcDataKey), flaws: denseChoices(npcDataKey), price: record, P7B_TRIAL: record,
    })(root, ref, '');
    const cultures = record(root.cultures, ref, 'cultures');
    const cultureIds = Object.keys(cultures);
    if (!cultureIds.length) fail(ref, 'cultures', 'expected at least one culture');
    for (const id of cultureIds) {
        npcDataKey(id, `${npcGeneratorFile}#${id}`, 'id');
        record(cultures[id], `${npcGeneratorFile}#cultures`, id);
    }
    catalog(cultures, npcGeneratorFile, cultureIds, object({ name: text, given: denseChoices(nameWord), epithets: denseChoices(nameWord) }));
    const originIds = Object.keys(npcLifeJson.origins);
    object(Object.fromEntries(originIds.map(id => [id, oneOf(...cultureIds)])))(root.originCulture, `${npcGeneratorFile}#originCulture`, '');
    const originRule = object({
        birthplaceId: npcWordIds(PLACES.filter(place => place.regionId !== null)), regionId: npcWordIds(REGIONS),
        upbringing: npcWordIds(UPBRINGINGS), occupation: oneOf(...PLAYER_PROFESSIONS), guildClass: oneOf('common', 'skilled'),
    });
    object(Object.fromEntries(originIds.map(id => [id, originRule])))(root.originProfile, `${npcGeneratorFile}#originProfile`, '');
    const trialRef = `${npcGeneratorFile}#P7B_TRIAL`;
    const age = ascending(within([CHARACTER_LIMITS.ageMin, CHARACTER_LIMITS.ageMax]));
    const stats = within([0, 100]);
    object({
        marker: literal('TRIAL'), age, ageWeightYoung: probability, youngAge: age, olderAge: age, stockSize: positive,
        startGoldMilli: literal(tuningJson.GOODS_STOCK_TRIAL.initialGoldMilli), npcCap: positive, traitCount: ascending(positive),
        statRange: ascending(stats), profileAxisRange: ascending(stats), contractWeeks: positive, wageMilli: ascending(positive),
        professionalAtCount: positive, expertAtCount: positive,
        household: object({
            unpaidAffectionLoss: stats, unpaidObedienceLoss: stats, mansionObedienceGain: stats, stressObedienceLoss: stats,
            unpaidRefusalWeeks: positive, stressRefusalHits: positive, lifelongAffectionMin: stats, lifelongObedienceMin: stats,
            lifelongAskGapWeeks: positive,
            renewalWageMultiplier: (value, ref, field) => {
                if (typeof value !== 'number' || !Number.isFinite(value) || value < 1)
                    fail(ref, field, 'expected finite number >= 1');
            },
            renewalWageStepMilli: literal(SOCIAL_RESOURCE_SCALE), quadrantSplit: stats,
        }),
    })(root.P7B_TRIAL, trialRef, '');
    const trial = root.P7B_TRIAL as NpcGeneratorCatalog['P7B_TRIAL'];
    if (trial.traitCount[1] > WORLD_TRAITS.length)
        fail(trialRef, 'traitCount', `expected at most ${WORLD_TRAITS.length} available traits`);
    if (trial.youngAge[0] !== trial.age[0] || trial.youngAge[1] + 1 !== trial.olderAge[0] || trial.olderAge[1] !== trial.age[1])
        fail(trialRef, 'age', 'expected young and older ranges to partition the adult age range');
    if (trial.professionalAtCount >= trial.expertAtCount)
        fail(trialRef, 'expertAtCount', 'expected greater than professionalAtCount');
    if (trial.wageMilli.some(wage => wage % SOCIAL_RESOURCE_SCALE !== 0))
        fail(trialRef, 'wageMilli', 'expected whole Gold amounts in milli');
    const sourceRange = ascending(stats);
    const sources = record(root.sources, ref, 'sources');
    for (const id of Object.keys(sources)) {
        if (!npcSourceIds.includes(id as NpcSourceId)) fail(`${npcGeneratorFile}#${id}`, 'id', 'unknown id');
    }
    for (const id of npcSourceIds) {
        const guild = id === 'guild';
        record(sources[id], `${npcGeneratorFile}#sources`, id);
        object({
            status: literal(guild ? 'servant' : 'slave'), mind: sourceRange, skills: sourceRange, beauty: sourceRange,
            obedience: sourceRange, affection: sourceRange, past: ascending(nonnegative),
            socialClass: denseChoices(guild ? oneOf('common', 'skilled') : literal('lower')),
        })(sources[id], `${npcGeneratorFile}#${id}`, '');
        const classes = (sources[id] as NpcSourceProfile).socialClass;
        if (guild && (!classes.includes('common') || !classes.includes('skilled')))
            fail(`${npcGeneratorFile}#${id}`, 'socialClass', 'expected common and skilled');
    }
    const measurements: Rule = (value, rowRef, field) => {
        if (value === null) return;
        object({ chestCm: within(CHARACTER_LIMITS.chestCm), waistCm: within(CHARACTER_LIMITS.waistCm),
            hipsCm: within(CHARACTER_LIMITS.hipsCm), disclosure: oneOf('known', 'unknown'),
        })(value, rowRef, field);
    };
    object({
        presentation: denseChoices(literal('feminine')), skinTone: denseChoices(npcWordIds(SKIN_TONES)), eyeColor: denseChoices(npcWordIds(EYE_COLORS)),
        hair: object({ color: denseChoices(npcWordIds(HAIR_COLORS)), length: denseChoices(npcWordIds(HAIR_LENGTHS)),
            texture: denseChoices(npcWordIds(HAIR_TEXTURES)), style: denseChoices(npcWordIds(HAIR_STYLES)) }),
        face: object({ shape: denseChoices(npcWordIds(FACE_SHAPES)), features: denseChoices(denseChoices(npcWordIds(FACE_FEATURES), true)) }),
        build: denseChoices(npcWordIds(BUILDS)), heightCm: denseChoices(within(CHARACTER_LIMITS.heightCm)),
        weightKg: denseChoices(within(CHARACTER_LIMITS.weightKg)), measurements: denseChoices(measurements),
        outfit: denseChoices(oneOf('role_default', ...OUTFITS.map(outfit => outfit.id))),
    })(root.appearance, `${npcGeneratorFile}#appearance`, '');
    object({
        baseMilli: object({ guild: positive, 'auction-house': positive, 'slave-market': positive, lot: positive }),
        skillPointBps: positive, beautyPointBps: positive, sexExpLevelBps: positive,
        levelValue: object({ novice: nonnegative, professional: positive, expert: positive }),
        conditionFactor: literal(1), sellShare: probability,
    })(root.price, `${npcGeneratorFile}#price`, '');
    return root as unknown as NpcGeneratorCatalog;
}

